<?php
defined('ABSPATH') || exit;

/** Simple, server-issued revision-safe workbooks; legacy eight-stage books remain supported. */
final class CAFCC_Review_V5_XLSX {
    const HEADERS=array('Stable ID','Revision','Source Hash','Owner Decision','Corrected Node IDs','Reviewer Notes','Question HTML SHA-256','Answer HTML SHA-256');
    public static function content_hash($r,$kind){return hash('sha256',$r['data']['rich_content'][$kind]['body_html']??'');}
    public static function export($ids){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;$old=CAFCC_Review_XLSX::export($ids);if(is_wp_error($old))return $old;
        $book=CAFCC_Review_XLSX::decode($old['base64']);$book['Approval Decisions']=array(self::HEADERS);foreach($ids as $id){$r=CAFCC_Studio::get($id);$book['Approval Decisions'][]=array($r['stable_id'],$r['revision'],$r['source_hash'],'','',$r['data']['review_notes'],self::content_hash($r,'question'),self::content_hash($r,'answer'));}
        foreach($book['Batch Manifest'] as &$line){if(($line[0]??'')==='format')$line[1]='CAFCC-XLSX-2';if(($line[0]??'')==='instructions')$line[1]='Use only Needs Review, Publish or Reject. Corrected numeric node IDs and notes are optional. Upload → Validate → inspect conflicts → Apply. Publication runs the same complete source/answer/taxonomy/content/permission checks as Studio. Stale books cannot replace newer corrections.';}unset($line);
        $encoded=CAFCC_Review_XLSX::encode($book);return is_wp_error($encoded)?$encoded:array('base64'=>$encoded,'filename'=>'cafcc-private-owner-review-v05.xlsx');
    }
    public static function preview($encoded){
        if(is_wp_error($e=CAFCC_Studio::admin()))return $e;try{$book=CAFCC_Review_XLSX::decode($encoded);}catch(Throwable $e){try{$portable=CAFCC_Review_XLSX::decode($encoded,array('Source Inventory','Questions','Answers','Topic Hierarchy','Exceptions','Progress Summary','Import Manifest','Approval Decisions'));return self::portable_preview($portable);}catch(Throwable $nested){return CAFCC_Repository::error($nested->getMessage());}}
        if(($book['Approval Decisions'][0]??array())!==self::HEADERS)return CAFCC_Repository::error('Keep the eight simple decision columns unchanged.');
        $key='';foreach($book['Batch Manifest'] as $line)if(($line[0]??'')==='batch_key')$key=$line[1]??'';
        global $wpdb;$bt=CAFCC_Bank_DB::table('batches');$batch=$wpdb->get_row($wpdb->prepare("SELECT * FROM $bt WHERE batch_key=%s AND batch_type='excel' AND status='exported' AND owner_id=%d",$key,get_current_user_id()),ARRAY_A);if(!$batch)return CAFCC_Repository::error('Export a current WordPress-issued review workbook first.',409);$manifest=json_decode($batch['manifest'],true);if($manifest['expires']<time())return CAFCC_Repository::error('Workbook expired; export current revisions.',409);
        $decisions=array();$conflicts=array();$seen=array();foreach(array_slice($book['Approval Decisions'],1) as $i=>$line){$line=array_pad($line,8,'');$signed=$manifest['records'][$line[0]]??null;$r=$signed?CAFCC_Studio::get($signed['id']):null;
            if(!$r||isset($seen[$line[0]])||(string)$r['revision']!==$line[1]||(string)$signed['revision']!==$line[1]||$r['source_hash']!==$line[2]||!hash_equals(self::content_hash($r,'question'),$line[6])||!hash_equals(self::content_hash($r,'answer'),$line[7])){$conflicts[]=array('row'=>$i+2,'message'=>'Unknown, duplicate, altered or stale identity/content revision. Existing corrections are retained.');continue;}$seen[$line[0]]=true;
            if(!in_array($line[3],array('','Needs Review','Publish','Reject'),true)){$conflicts[]=array('row'=>$i+2,'message'=>'Choose Needs Review, Publish or Reject.');continue;}$ids=null;if(trim($line[4])){if(!preg_match('/^[1-9][0-9]*(?:\s*,\s*[1-9][0-9]*){0,29}$/D',trim($line[4]))){$conflicts[]=array('row'=>$i+2,'message'=>'Corrected tags need existing numeric node IDs.');continue;}$ids=array_map('intval',preg_split('/\s*,\s*/',trim($line[4])));}
            if($line[3]||$ids!==null||$line[5]!==$r['data']['review_notes'])$decisions[]=array('id'=>$r['id'],'revision'=>$r['revision'],'action'=>$line[3]?array('Needs Review'=>'needs_review','Publish'=>'publish','Reject'=>'reject')[$line[3]]:'','classification'=>$ids,'notes'=>sanitize_textarea_field($line[5]));
        }
        if(!$conflicts&&$decisions){$test=CAFCC_Academic::transaction(function()use($decisions){$r=self::execute($decisions);return is_wp_error($r)?$r:new WP_Error('cafcc_v5_excel_rollback','Preview only');});if($test->get_error_code()!=='cafcc_v5_excel_rollback')$conflicts[]=array('row'=>'batch','message'=>$test->get_error_message());}
        $token=wp_generate_uuid4();set_transient('cafcc_v5_excel_'.$token,array('owner'=>get_current_user_id(),'batch_key'=>$key,'decisions'=>$decisions,'conflicts'=>$conflicts),1800);return array('token'=>$token,'decisions'=>$decisions,'conflicts'=>$conflicts,'can_apply'=>!$conflicts&&count($decisions)>0);
    }
    public static function portable_preview($book){
        if(($book['Approval Decisions'][0]??array())!==self::HEADERS)return CAFCC_Repository::error('Invalid portable owner-decision columns.');$format='';foreach($book['Import Manifest']??array() as $p)if(($p[0]??'')==='format')$format=$p[1]??'';if($format!=='CAFCC-FR-PRIVATE-1')return CAFCC_Repository::error('Unknown private corpus workbook format.');
        global $wpdb;$rt=CAFCC_Studio::table();$bt=CAFCC_Bank_DB::table('batches');$manifest=array('owner'=>get_current_user_id(),'issued'=>time(),'expires'=>time()+DAY_IN_SECONDS,'records'=>array());
        foreach(array_slice($book['Approval Decisions'],1) as $line){$sid=$line[0]??'';$id=$wpdb->get_var($wpdb->prepare("SELECT r.id FROM $rt r JOIN $bt b ON b.batch_key=r.batch_key AND b.batch_type='research' AND b.owner_id=%d WHERE r.stable_id=%s",get_current_user_id(),$sid));$r=$id?CAFCC_Studio::get($id):null;if(!$r||(int)$r['revision']!==1||($line[1]??'')!=='1'||$r['source_hash']!==($line[2]??'')||!hash_equals(self::content_hash($r,'question'),$line[6]??'')||!hash_equals(self::content_hash($r,'answer'),$line[7]??''))return CAFCC_Repository::error('Portable workbook conflict at '.$sid.': import its matching JSON first; any existing correction requires a fresh WordPress export. Nothing was overwritten.',409);if(isset($manifest['records'][$sid]))return CAFCC_Repository::error('Duplicate portable candidate identity.');$manifest['records'][$sid]=array('id'=>(int)$r['id'],'revision'=>1,'source_hash'=>$r['source_hash']);}
        if(!$manifest['records']||count($manifest['records'])>200)return CAFCC_Repository::error('Use a private workbook of 1–200 imported records.');$key=wp_generate_uuid4();if(false===$wpdb->insert($bt,array('batch_key'=>$key,'owner_id'=>get_current_user_id(),'batch_type'=>'excel','status'=>'exported','manifest'=>wp_json_encode($manifest),'created_at'=>current_time('mysql',true))))return CAFCC_Repository::error('Cannot register validated private workbook.',500);
        $normal=array_fill_keys(CAFCC_Review_XLSX::SHEETS,array(array('Private review')));$normal['Approval Decisions']=$book['Approval Decisions'];$normal['Batch Manifest']=array(array('Key','Value'),array('batch_key',$key),array('format','CAFCC-XLSX-2'));$bytes=CAFCC_Review_XLSX::encode($normal);if(is_wp_error($bytes))return $bytes;return self::preview($bytes);
    }
    public static function execute($decisions){
        foreach($decisions as $d){$r=CAFCC_Studio::get($d['id'],true);if(!$r||(string)$r['revision']!==(string)$d['revision'])return CAFCC_Repository::error('A question changed after preview. Export a fresh workbook.',409);}
        foreach($decisions as $d){$r=CAFCC_Studio::get($d['id']);if($d['classification']!==null||$d['notes']!==$r['data']['review_notes']){$data=$r['data'];if($d['classification']!==null){$data['classification']=$d['classification'];if($d['notes'])$data['reasoning']=$d['notes'];}$data['review_notes']=$d['notes'];$r=CAFCC_Studio::save($r['id'],array('expected_revision'=>$r['revision'],'data'=>$data));if(is_wp_error($r))return $r;}if($d['action']){$r=CAFCC_Release_V5::decision($r['id'],array('expected_revision'=>$r['revision'],'action'=>$d['action'],'confirmed'=>true));if(is_wp_error($r))return $r;}}return true;
    }
    public static function apply($token){if(is_wp_error($e=CAFCC_Studio::admin()))return $e;if(!is_string($token)||!preg_match('/^[a-f0-9-]{36}$/D',$token))return CAFCC_Repository::error('Invalid preview token.');$p=get_transient('cafcc_v5_excel_'.$token);if(!$p||$p['owner']!==get_current_user_id()||$p['conflicts']||!$p['decisions'])return CAFCC_Repository::error('Validate a conflict-free workbook first.',409);return CAFCC_Academic::transaction(function()use($p,$token){global $wpdb;$bt=CAFCC_Bank_DB::table('batches');$b=$wpdb->get_row($wpdb->prepare("SELECT * FROM $bt WHERE batch_key=%s FOR UPDATE",$p['batch_key']),ARRAY_A);if(!$b||$b['status']!=='exported')return CAFCC_Repository::error('This workbook was already used.',409);$r=self::execute($p['decisions']);if(is_wp_error($r))return $r;if(false===$wpdb->update($bt,array('status'=>'applied'),array('id'=>$b['id'])))return CAFCC_Repository::error('Cannot retain workbook audit.',500);delete_transient('cafcc_v5_excel_'.$token);return array('applied'=>count($p['decisions']),'published_only_after'=>'authenticated owner validation');});}
    public static function init(){add_action('rest_api_init',function(){$p=function($r){return CAFCC_REST::permission($r,true);};foreach(array('export','preview','apply') as $action)register_rest_route('cafcc/v5','/admin/excel/'.$action,array('methods'=>'POST','permission_callback'=>$p,'callback'=>function($r)use($action){$v=CAFCC_Studio::body($r,5000000);if(is_wp_error($v))return $v;return $action==='export'?self::export($v['ids']??null):($action==='preview'?self::preview($v['base64']??null):self::apply($v['token']??null));}));});}
}
